package cn.yilan.news;

import java.util.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.io.IOException;
import org.json.*;
import cn.yilan.news.NewsEngine.*;

/** Deterministic storage transaction and history decisions; no real provider or network. */
public final class HistoryStorageTest {
  private static void check(boolean value,String reason){if(!value)throw new AssertionError(reason);}
  private static Article article(String source,String day){Article a=new Article();a.id=source+day;a.source=source;a.sourceName=source;a.title="普通新闻";a.url="https://example.com/"+a.id;a.published=java.time.LocalDate.parse(day).atTime(12,0).atZone(java.time.ZoneId.of("Asia/Shanghai")).toInstant().toEpochMilli();return a;}
  private static AiEngine.Result result(Article a){AiEngine.Result r=new AiEngine.Result();r.profile="test-profile";r.model="fixed-model";r.at=1;r.since=ContentDates.day(a);r.days.add(r.since);AiEngine.Group g=new AiEngine.Group();g.title="已选";g.reports.add(a);r.groups.add(g);return r;}
  private static final class Memory implements AiResultStore.Files {
    final Map<String,byte[]> data=new HashMap<>();String fail="";
    public byte[] read(String name,int limit)throws Exception{byte[] bytes=data.get(name);if(bytes!=null&&bytes.length>limit)throw new IOException("limit");return bytes;}
    public void write(String name,byte[] bytes)throws Exception{if(name.equals(fail))throw new IOException("disk failure");data.put(name,bytes.clone());}
    public Set<String> names(){return new HashSet<>(data.keySet());}
    public void delete(String name){data.remove(name);data.remove(name+".bak");data.remove(name+".new");}
  }
  public static void main(String[] args)throws Exception{
    NewsEngine engine=new NewsEngine(new String(Files.readAllBytes(Paths.get(args[0])),StandardCharsets.UTF_8),(s,u)->{throw new IOException("network forbidden");});
    Article a=article("chinanews","2026-11-09"),b=article("chinanews","2026-11-08"),ai=article("infoq-cn","2026-11-07");String scope=AiEngine.FEATURED_NEWS;
    Map<String,Snapshot> snapshots=new HashMap<>();Snapshot snapshot=new Snapshot(a.source);snapshot.items.add(a);snapshot.fetched=1;snapshot.cached=true;snapshots.put(a.source,snapshot);Map<String,AiEngine.Result> results=new LinkedHashMap<>();AiEngine.Result saved=result(b);results.put(ContentDates.key(scope,ContentDates.day(b)),saved);Map<String,Boolean> enabled=new HashMap<>();enabled.put(a.source,true);enabled.put(ai.source,true);
    List<Article> local=AiHistory.local(Collections.singletonList(ai),snapshots,results);AiHistory.Plan plan=AiHistory.plan(false,Arrays.asList("2026-11-09","2026-11-08","2026-11-07"),results,Collections.emptySet(),local,engine,enabled,Collections.emptySet(),false);
    check(plan.saved.equals(Collections.singletonList("2026-11-08"))&&plan.local.equals(Collections.singletonList("2026-11-09"))&&plan.fetch.equals(Collections.singletonList("2026-11-07")),"Independent date planning must reuse snapshot-only news and saved dates");
    check(!AiHistory.canRecheck(snapshot,"2026-11-01")&&AiHistory.canRecheck(null,"2026-11-01"),"Nonpaginated current list must not be fetched again for a date older than its oldest item");
    plan=AiHistory.plan(false,Collections.singletonList("2026-11-07"),results,Collections.singleton(ContentDates.key(scope,"2026-11-07")),local,engine,enabled,Collections.emptySet(),false);check(plan.fetch.isEmpty()&&plan.unavailable.size()==1,"Persisted empty check must not repeatedly fetch unrelated content");
    NewsArchive archive=new NewsArchive();check(archive.articles().isEmpty(),"Reading old snapshots must not manufacture archive acquisition history");snapshot.cached=false;archive.accept(snapshot,engine,System.currentTimeMillis());JSONObject invalid=archive.json();invalid.getJSONArray("records").put(new JSONObject());boolean rejected=false;try{archive.restoreChecked(invalid,engine);}catch(Exception e){rejected=true;}check(rejected&&archive.articles().size()==1,"Malformed archive must not clear valid memory records");
    AiEngine.Result legacy=result(a);legacy.groups.addAll(result(b).groups);results.clear();results.put(scope,legacy);AiEngine.Result newer=result(a);newer.at=10;results.put(ContentDates.key(scope,"2026-11-09"),newer);check(AiHistory.migrate(results)&&results.get(ContentDates.key(scope,"2026-11-09"))==newer&&results.containsKey(ContentDates.key(scope,"2026-11-08")),"Partial migration must fill missing days without overwriting existing daily selection");check(!AiHistory.migrate(results),"Migration must be idempotent");
    Memory files=new Memory();AiResultStore store=new AiResultStore(files);JSONObject rows=new JSONObject();for(Map.Entry<String,AiEngine.Result> row:results.entrySet())rows.put(row.getKey(),row.getValue().json());JSONObject state=new JSONObject().put("results",rows);files.data.put("ai-results-v1.json",state.toString().getBytes(StandardCharsets.UTF_8));check(store.load().getJSONObject("results").has(scope),"Legacy single file remains readable");store.save(state);JSONObject loaded=new AiResultStore(files).load();check(loaded.getJSONObject("results").has(ContentDates.key(scope,"2026-11-08")),"Sharded history must reopen without losing migrated dates");
    byte[] committed=files.data.get("ai-results-v1.json").clone();JSONObject modified=new JSONObject(state.toString());modified.getJSONObject("results").getJSONObject(ContentDates.key(scope,"2026-11-08")).put("text","新结果");files.fail="ai-results-v1.json";rejected=false;try{store.save(modified);}catch(Exception e){rejected=true;}check(rejected&&Arrays.equals(committed,files.data.get("ai-results-v1.json"))&&!new AiResultStore(files).load().getJSONObject("results").getJSONObject(ContentDates.key(scope,"2026-11-08")).optString("text").equals("新结果"),"Failed atomic head commit must leave every old date readable");files.fail="";
    JSONObject many=new JSONObject();char[] padding=new char[600000];Arrays.fill(padding,'x');for(int i=1;i<=12;i++){AiEngine.Result r=result(article("chinanews",String.format("2026-10-%02d",i)));r.text=new String(padding);many.put(ContentDates.key(scope,r.since),r.json());}JSONObject large=new JSONObject().put("results",many);check(large.toString().getBytes(StandardCharsets.UTF_8).length>6*1024*1024,"Fixture must exceed former shared limit");store.save(large);check(new AiResultStore(files).load().getJSONObject("results").length()==12,"More than 6MiB of dated history must survive a fresh store instance");
    AiEngine.Result empty=new AiEngine.Result();empty.profile="p";empty.model="m";empty.since="2026-11-02";JSONObject onlyEmpty=new JSONObject().put("results",new JSONObject().put(ContentDates.key(scope,empty.since),empty.json()));store.save(onlyEmpty);check(new AiResultStore(files).load().getJSONObject("results").has(ContentDates.key(scope,empty.since)),"Successful zero-group result must remain a persistent dated result");
    JSONObject index=new JSONObject(new String(files.data.get("ai-results-v1.json"),StandardCharsets.UTF_8));String blob="ai-day-"+index.getJSONObject("dailyFiles").getString(ContentDates.key(scope,empty.since))+".json";files.data.put(blob,"broken".getBytes(StandardCharsets.UTF_8));AiResultStore broken=new AiResultStore(files);rejected=false;try{broken.load();}catch(Exception e){rejected=true;}check(rejected,"Missing or corrupted day must be explicit, not an empty history");byte[] before=files.data.get("ai-results-v1.json").clone();rejected=false;try{broken.save(new JSONObject());}catch(Exception e){rejected=true;}check(rejected&&Arrays.equals(before,files.data.get("ai-results-v1.json")),"Read failure must lock writes and preserve original index");broken.clear();check(broken.load().length()==0&&files.names().isEmpty(),"Explicit forget must clear index, blobs and orphans");
    files.data.put(blob+".new",new byte[]{1});files.data.put(blob+".bak",new byte[]{2});rejected=false;try{broken.load();}catch(Exception e){rejected=true;}check(rejected,"Unindexed daily remnants must not be silently treated as empty");broken.clear();check(files.names().isEmpty(),"Forget must remove orphan .new/.bak AtomicFile remnants as well");
    files.data.put("ai-results-v1.json",new JSONObject().put("results",new JSONObject().put(ContentDates.key(scope,"2026-11-01"),new JSONObject().put("broken",true))).toString().getBytes(StandardCharsets.UTF_8));rejected=false;try{broken.load();}catch(Exception e){rejected=true;}check(rejected,"Malformed legacy result row must not be silently dropped before automatic writes");
    System.out.println("PASS: history local reuse, independent dates, missing-day checks and partial migration");System.out.println("PASS: transactional daily storage, >6MiB restart, write/read faults and empty-day retention");
  }
}
